-- Can `launcher` (a catalog entry) fire `ordinance` (an ordinance.lua
-- entry)? Launchers carry no damage of their own, so this compatibility
-- check is the whole of their firing logic at the data layer. Matches the
-- ordinance's own `compatible_weapon` against the launcher's
-- `launcher_type` - the "enforced by data, not by separate tables per
-- weapon" rule §2.8 specifies. Returns false for a non-launcher or a
-- launcher/ordinance pair of the wrong subtype (e.g. a nuclear torpedo in
-- a general launcher).
function M.accepts(launcher, ordinance)
	if not (launcher and ordinance) then
		return false
	end
	return launcher.launcher_type ~= nil
		and ordinance.compatible_weapon == launcher.launcher_type
end

return M
